{
  "application": {
    "name": "treasury-console",
    "apiBaseUrl": "/api",
    "telemetry": true,
    "features": {
      "portfolio": true,
      "swaps": false,
      "assetOnboarding": true
    }
  },
  "networkConfig": {
    "defaultEnvironment": "staging",
    "environments": {
      "production": {
        "chain": {
          "name": "Ethereum Mainnet",
          "chainId": 1,
          "rpcUrl": "https://eth.llamarpc.com",
          "explorerUrl": "https://etherscan.io",
          "deprecatedGoerliFallbackUrl": "https://goerli.infura.io/v3/${INFURA_KEY}"
        },
        "rpcPolicy": {
          "readRpcUrl": "https://eth.llamarpc.com",
          "writeRpcUrl": "https://eth.llamarpc.com",
          "sequencerSubmissionUrl": null,
          "sequencerSubmissionOnly": null,
          "sequencerAcceptedMethods": [],
          "retryableSubmissionErrors": [],
          "terminalSubmissionErrors": [
            "execution reverted"
          ]
        },
        "contracts": {
          "multicall3": "0xcA11bde05977b3631167028862bE2a173976CA11"
        },
        "tokens": {
          "WETH": "0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2",
          "USDC": "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48",
          "USDC.e": null
        },
        "assetOnboarding": {
          "enabled": true,
          "preferredRoute": "native",
          "canonicalBridge": {
            "enabled": false
          }
        },
        "finalityPolicy": {
          "withdrawalsToEthereumAreInstant": null,
          "challengeWindowBlocks": null,
          "forceIncludePeriodBlocks": null
        }
      },
      "staging": {
        "chain": {
          "name": "Ethereum Sepolia",
          "chainId": 11155111,
          "rpcUrl": "https://ethereum-sepolia-rpc.publicnode.com",
          "explorerUrl": "https://sepolia.etherscan.io",
          "deprecatedGoerliFallbackUrl": "https://goerli.infura.io/v3/${INFURA_KEY}"
        },
        "rpcPolicy": {
          "readRpcUrl": "https://ethereum-sepolia-rpc.publicnode.com",
          "writeRpcUrl": "https://ethereum-sepolia-rpc.publicnode.com",
          "sequencerSubmissionUrl": null,
          "sequencerSubmissionOnly": null,
          "sequencerAcceptedMethods": [],
          "retryableSubmissionErrors": [],
          "terminalSubmissionErrors": [
            "execution reverted"
          ]
        },
        "contracts": {
          "multicall3": "0xcA11bde05977b3631167028862bE2a173976CA11"
        },
        "tokens": {
          "WETH": "0xfff9976782d46cc05630d1f6ebab18b2324d6b14",
          "USDC": "0x1c7D4B196Cb0C7B01d743Fbc6116a902379C7238",
          "USDC.e": null
        },
        "assetOnboarding": {
          "enabled": true,
          "preferredRoute": "native",
          "canonicalBridge": {
            "enabled": false
          }
        },
        "finalityPolicy": {
          "withdrawalsToEthereumAreInstant": null,
          "challengeWindowBlocks": null,
          "forceIncludePeriodBlocks": null
        }
      }
    }
  },
  "wallet": {
    "autoConnect": false,
    "requiredConfirmations": 2,
    "enabledConnectors": [
      "injected",
      "walletConnect"
    ]
  },
  "retry": {
    "attempts": 3,
    "backoffMs": 500
  }
}

